import tempfile
import torch
import torch.nn as nn
from topologies import Trainer, build, synth
root = tempfile.mkdtemp()
@synth.generator
def samples(ctx):
    features = torch.randn(4, generator=ctx.rng.torch)
    teacher_probabilities = torch.softmax(torch.stack((features[0], -features[0])), dim=0)
    return {"inputs": synth.Tensor(features), "labels": int(features[0] > 0), "teacher_probabilities": synth.Tensor(teacher_probabilities)}
class ContinualModel(nn.Module):
    def __init__(self):
        super().__init__()
        self.network = build("mlp", "tiny", in_features=4, out_features=4)
    def forward(self, inputs):
        logits = self.network(inputs)
        return {"new_logits": logits[:, :2], "old_logits": logits[:, 2:]}
ds = synth.Spec("lwf-data", generator=samples, size=12, splits={"train": 1.0}, seed=11, root=root, monitor="none").run()
train = ds.for_recipe("structured-objective", split="train")
trainer = Trainer(ContinualModel(), train, recipe="structured-objective", recipe_config={"loss": "lwf", "loss_kwargs": {"temperature": 2.0, "lambda_old": 1.0}, "bindings": {"logits_or_prediction": {"output": "new_logits"}, "targets": {"batch": "labels"}, "old_logits": {"output": "old_logits"}, "old_probabilities": {"batch": "teacher_probabilities"}}}, batch_size=4, max_epochs=1, device="cpu")
trainer.fit()
